sys_aix_widget.script:
(function(data, _options, input) {
var iDefaultPageSize = 20;
var aRenameFieldCandidates = ['short_description', 'description', 'name', 'title'];
var aCopySkipFields = [
  'sys_id',
  'sys_created_on',
  'sys_created_by',
  'sys_updated_on',
  'sys_updated_by',
  'sys_mod_count'
];

  var oHandlers = {
    listTables: fnHandleListTables,
    getTableMeta: fnHandleGetTableMeta,
    listRecords: fnHandleListRecords,
    listFields: fnHandleListFields,
    getRecord: fnHandleGetRecord,
    getField: fnHandleGetField,
    renameRecord: fnHandleRenameRecord,
    copyRecord: fnHandleCopyRecord,
    setField: fnHandleSetField,
    getVersion: fnHandleGetVersion,
    getEnv: fnHandleGetEnv,
    listTableTree: fnHandleListTableTree,
    findInTable: fnHandleFindInTable,
    compareRecords: fnHandleCompareRecords,
    getChkdsk: fnHandleGetChkdsk
  };
  var sAction = (input && input['action']) || '';
  var fnHandler = oHandlers[sAction];
  if (!fnHandler) {
    data['isError'] = true;
    data['errorMessage'] = gs.getMessage('Bad command or file name.');
    return;
  } // if: unknown action
  fnHandler();

  function fnPatternToQuery(sField, sPattern) {
    var sTrimmed = String(sPattern || '').trim();
    if (!sTrimmed) return ''; // no filter given
    var bLead = sTrimmed.charAt(0) === '*';
    var bTrail = sTrimmed.charAt(sTrimmed.length - 1) === '*';
    var bHasSingle = sTrimmed.indexOf('?') !== -1;
    var sCore = sTrimmed.replace(/[*?]/g, '');
    if (!sCore) return ''; // pattern was only wildcards, so it matches everything
    if (bHasSingle) return sField + 'LIKE' + sCore; // ? has no encoded-query form, so widen to a contains match
    if ((bLead) && (bTrail)) return sField + 'LIKE' + sCore;
    if (bTrail) return sField + 'STARTSWITH' + sCore;
    if (bLead) return sField + 'ENDSWITH' + sCore;
    return sField + '=' + sCore;
  } // fnPatternToQuery

  function fnWildcardRegExp(sPattern) {
    var sTrimmed = String(sPattern || '').trim();
    if (!sTrimmed) return null; // no filter given
    var sEscaped = sTrimmed.replace(/[.+^${}()|[\]\\]/g, '\\$&').replace(/\*/g, '.*').replace(/\?/g, '.');
    return new RegExp('^' + sEscaped + '$', 'i');
  } // fnWildcardRegExp

  function fnResolveLabelField(grTable) {
    var iCandidate = 0;
    while (iCandidate < aRenameFieldCandidates.length) {
      if (grTable.isValidField(aRenameFieldCandidates[iCandidate])) {
        return aRenameFieldCandidates[iCandidate];
      } // if: table has this candidate field
      iCandidate++;
    } // while: walk the preference list
    return '';
  } // fnResolveLabelField

  function fnResolveRecord(grTable, sIdentifier, sTable) {
    var bLooksLikeSysId = /^[0-9a-f]{32}$/i.test(sIdentifier);
    var bFound = false;
