      iScanned++;
      if (iScanned > iMaxMatches) break; // if: only keep the capped page, the extra row just signals more exist
      if (!grTable.getElement(sSearchField).canRead()) continue; // if: field-level read denied, skip this row entirely
      aMatches.push({
        sIdentifier: bHasNumber ? grTable.getValue('number') : grTable.getUniqueValue().substring(0, 8),
        sLine: grTable.getValue(sSearchField)
      });
    } // while: collect every readable match up to the cap
    data['aMatches'] = aMatches;
    data['bTruncated'] = iScanned > iMaxMatches;
  } // fnHandleFindInTable

  function fnHandleCompareRecords() {
    var sTable = String(input['sTable'] || '');
    var sIdentifierA = String(input['sIdentifierA'] || '');
    var sIdentifierB = String(input['sIdentifierB'] || '');
    var iMaxDiffs = 10; // real COMP.COM stops after 10 mismatches too
    if ((!sTable) || (!gs.tableExists(sTable)) || (!sIdentifierA) || (!sIdentifierB)) {
      data['isError'] = true;
      data['errorMessage'] = gs.getMessage('Bad command or file name.');
      return;
    } // if: missing required params
    var grRecordA = new GlideRecordSecure(sTable);
    if ((!fnResolveRecord(grRecordA, sIdentifierA, sTable)) || (!grRecordA.canRead())) {
      data['isError'] = true;
      data['errorMessage'] = gs.getMessage('File not found - {0}', [sIdentifierA]);
      return;
    } // if: first record missing, misnested, or unreadable
    var grRecordB = new GlideRecordSecure(sTable);
    if ((!fnResolveRecord(grRecordB, sIdentifierB, sTable)) || (!grRecordB.canRead())) {
      data['isError'] = true;
      data['errorMessage'] = gs.getMessage('File not found - {0}', [sIdentifierB]);
      return;
    } // if: second record missing, misnested, or unreadable
    var aDiffs = [];
    var aElements = grRecordA.getElements();
    var iElement = 0;
    while ((iElement < aElements.length) && (aDiffs.length < iMaxDiffs)) {
      var grElementA = aElements[iElement];
      var sName = String(grElementA.getName());
      if ((grElementA.canRead()) && (grRecordB.isValidField(sName)) && (grRecordB.getElement(sName).canRead())) {
        var sValueA = grElementA.getDisplayValue();
        var sValueB = grRecordB.getElement(sName).getDisplayValue();
        if (sValueA !== sValueB) {
          aDiffs.push({sField: sName, sValueA: sValueA, sValueB: sValueB});
        } // if: values differ on a field both records can read
      } // if: field is readable on both records
      iElement++;
    } // while: walk record A's fields until the diff cap or field list is exhausted
    data['aDiffs'] = aDiffs;
    data['bTruncated'] = aDiffs.length >= iMaxDiffs;
  } // fnHandleCompareRecords

  function fnHandleGetChkdsk() {
    var sTable = String(input['sTable'] || '');
    if (!sTable) {
      var _GlideAggregate = new GlideAggregate('sys_db_object');
      _GlideAggregate.addNullQuery('super_class');
      _GlideAggregate.addQuery('name', 'NOT LIKE', 'sys_');
      _GlideAggregate.addAggregate('COUNT');
      _GlideAggregate.query();
      data['iDirCount'] = _GlideAggregate.next() ? parseInt(_GlideAggregate.getAggregate('COUNT'), 10) || 0 : 0;
      data['iRecordCount'] = -1; // -1 signals "not applicable at the volume root" - the client prints a CD-into-a-table hint instead
      return;
    } // if: at the instance root, only the base-table count is cheap to gather
    if (!gs.tableExists(sTable)) {
      data['isError'] = true;
      data['errorMessage'] = gs.getMessage('The system cannot find the path specified.');
      return;
    } // if: unknown table
    var grCurrent = new GlideRecordSecure(sTable);
    if (!grCurrent.canRead()) {
      data['isError'] = true;
      data['errorMessage'] = gs.getMessage('Access is denied.');
      return;
    } // if: no read access to this table
    var sParentSysId = fnTableSysId(sTable);
    var iDirCount = 0;
    if (sParentSysId) {
      var _GlideAggregateChild = new GlideAggregate('sys_db_object');
      _GlideAggregateChild.addQuery('super_class', sParentSysId);
      _GlideAggregateChild.addAggregate('COUNT');
      _GlideAggregateChild.query();
      iDirCount = _GlideAggregateChild.next() ? parseInt(_GlideAggregateChild.getAggregate('COUNT'), 10) || 0 : 0;
    } // if: table has a metadata row, count its direct child tables
    data['iDirCount'] = iDirCount;
    data['iRecordCount'] = fnCountRecords(sTable);
  } // fnHandleGetChkdsk
})(data, options, input);

