 } else if (this._oLocation.aTables.length > 0) {
 this._oLocation = {sDrive: sDrive, aTables: this._oLocation.aTables.slice(0, -1), sSysId: '', sRecordIdentifier: ''};
 } // if: pop the record, then one table level up its parent chain, else stay at root
